        return None
    return conn.execute("SELECT * FROM mentors WHERE edit_token = ?", (token,)).fetchone()


def insert_mentor(conn: sqlite3.Connection, name: str, company_title: str, role_tag: str,
                   bio: str, photo_filename: str, links: dict, source: str) -> tuple[int, str]:
    token = secrets.token_urlsafe(16)
    cur = conn.execute(
        """INSERT INTO mentors (name, company_title, role_tag, bio, photo_filename,
           fb_url, website_url, ig_url, blog_url, youtube_url, edit_token, source)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (name, company_title, role_tag or None, bio, photo_filename,
         links.get("fb_url") or None, links.get("website_url") or None,
         links.get("ig_url") or None, links.get("blog_url") or None,
         links.get("youtube_url") or None, token, source),
