input.text:
(function(){
  const results = [];
  document.querySelectorAll('.link-row').forEach((row, i) => {
    const urlInput = row.querySelector('input[type=url]');
    const btn = row.querySelector('.edit-label-btn');
    results.push({
      row: i,
      urlWidth: Math.round(urlInput.getBoundingClientRect().width),
      btnWidth: Math.round(btn.getBoundingClientRect().width)
    });
  });
  return JSON.stringify(results, null, 1);
})();

